

# This file was *autogenerated* from the file check_01_rank.sage
from sage.all_cmdline import *   # import sage library

_sage_const_2 = Integer(2); _sage_const_3 = Integer(3); _sage_const_4 = Integer(4); _sage_const_5 = Integer(5); _sage_const_1 = Integer(1); _sage_const_1en8 = RealNumber('1e-8'); _sage_const_1en6 = RealNumber('1e-6')# <Z_Y_linearly_independent>: {Z_1..Z_M, Y_1..Y_M} が C-線型独立
import os
_dir = os.path.dirname(os.path.abspath(__file__)) if "__file__" in dir() else "."
load(os.path.join(_dir, "../../_shared/operators.sage"))
import numpy as np
rep = CheckReport("Z_Y_linearly_independent: 特異値による数値ランク")
for M in [_sage_const_2 ,_sage_const_3 ,_sage_const_4 ,_sage_const_5 ]:
    rows = [Zop(m,M).reshape(-_sage_const_1 ) for m in range(_sage_const_1 ,M+_sage_const_1 )] + [Yop(m,M).reshape(-_sage_const_1 ) for m in range(_sage_const_1 ,M+_sage_const_1 )]
    A = np.array(rows)                      # (2M) x (4^M)
    sv = np.linalg.svd(A, compute_uv=False)
    smin, smax = float(sv.min()), float(sv.max())
    print(f"  M={M}: 2M={_sage_const_2 *M}, sigma_min={smin:.6e}, sigma_max={smax:.6e}, cond={smax/smin:.3f}")
    rep.truth(np.linalg.matrix_rank(A, tol=_sage_const_1en8 ) == _sage_const_2 *M, f"M={M}: 数値ランク = 2M")
    rep.truth(smin > _sage_const_1en6 , f"M={M}: 最小特異値が 0 から十分離れている")
    # 対比: Z_1 を 2 回入れると必ずランクが落ちる（判定が有意味であることの確認）
    A2 = np.array(rows + [Zop(_sage_const_1 ,M).reshape(-_sage_const_1 )])
    rep.truth(np.linalg.matrix_rank(A2, tol=_sage_const_1en8 ) == _sage_const_2 *M, f"M={M}: 重複を足してもランクは増えない")
rep.finish()

